import math
from scipy.special import gammaln

def a(l,n):
 if l<2:return 0.
 return (l-1)**2*(l+n-1)**2*.5*math.exp(gammaln((l-1)/2)+gammaln((l+n)/2)-gammaln((l+n+1)/2)-gammaln(l/2))
def bracket(l,n):
 m=n-1
 km=l*(l+m)**2/(2*l+m-1)
 kp=(l-1)**2*(l+m-1)/(2*l+m-1)
 return (km*a(l-1,n)+kp*a(l+1,n))/a(l,n)+n-l*(l+m-1)
for n in range(3,51):
 vals=[bracket(l,n) for l in range(2,101)]
 print(n, min(vals), vals.index(min(vals))+2, vals[:4])

